def _wz52_label(text: str) -> str:
    try:
        return ui_label(text)
    except Exception:
        return text


def _wz52_safe_json(raw):
    try:
        if isinstance(raw, dict):
            return raw
        fn = globals().get("safe_json_loads")
        if callable(fn):
            data = fn(raw)
            if isinstance(data, dict):
                return data
        return json.loads(str(raw or "{}"))
    except Exception:
        return {}


def _wz52_pdf_bytes(title: str, body: str):
    """Create a simple ATS-friendly PDF. Returns None if reportlab is unavailable."""
    try:
        from io import BytesIO
        from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.units import mm
        from reportlab.lib.enums import TA_LEFT
        from reportlab.lib import colors

        buffer = BytesIO()
        doc = SimpleDocTemplate(
            buffer,
            pagesize=A4,
            rightMargin=22 * mm,
            leftMargin=22 * mm,
            topMargin=20 * mm,
            bottomMargin=20 * mm,
        )
        styles = getSampleStyleSheet()
        title_style = ParagraphStyle(
            "WorkZoTitle",
            parent=styles["Heading1"],
            fontName="Helvetica-Bold",
            fontSize=16,
            leading=20,
            textColor=colors.HexColor("#111827"),
            spaceAfter=12,
            alignment=TA_LEFT,
        )
        body_style = ParagraphStyle(
            "WorkZoBody",
            parent=styles["BodyText"],
            fontName="Helvetica",
            fontSize=10.5,
            leading=15,
            textColor=colors.HexColor("#111827"),
            spaceAfter=8,
        )
        story = [Paragraph(html.escape(str(title or "Cover Letter")), title_style), Spacer(1, 6)]
        for block in str(body or "").split("\n"):
            if block.strip():
                story.append(Paragraph(html.escape(block.strip()), body_style))
            else:
                story.append(Spacer(1, 6))
        doc.build(story)
        buffer.seek(0)
        return buffer.getvalue()
    except Exception:
        return None


def _wz52_render_downloads(prefix: str, text: str, filename_base: str):
    c1, c2 = st.columns(2)
    with c1:
        st.download_button(
            f"⬇️ Download {prefix} as TXT",
            data=str(text or ""),
            file_name=f"{filename_base}.txt",
            mime="text/plain",
            use_container_width=True,
            key=f"wz52_{filename_base}_txt",
        )
    with c2:
        pdf_data = _wz52_pdf_bytes(prefix, text)
        if pdf_data:
            st.download_button(
                f"⬇️ Download {prefix} as PDF",
                data=pdf_data,
                file_name=f"{filename_base}.pdf",
                mime="application/pdf",
                use_container_width=True,
                key=f"wz52_{filename_base}_pdf",
            )
        else:
            st.caption("PDF export is unavailable because ReportLab is not installed.")


def _wz52_generate_cover_letter(company_name: str, target_role: str, language: str, job_description: str):
    cv_text = str(st.session_state.get("cv_text") or st.session_state.get("clean_structured_cv_text") or "").strip()
    prompt = f"""
You are WorkZo AI. Create practical, honest application documents using ONLY the candidate CV and job description.
Do not invent companies, achievements, skills, degrees, salaries, language levels, phone numbers, email addresses, names, addresses, or personal details.
If company name is missing, use [Company Name]. If hiring manager is unknown, use [Hiring Manager's Name]. If candidate name/contact is missing, use [Your Name], [Your Phone], and [Your Email].

Template rules:
- Full cover letter must use a clean letter format: candidate contact, date, employer placeholder/company, greeting, 3-4 short paragraphs, closing, candidate name.
- Short email must start with "Dear [Hiring Manager's Name]," or "Dear Hiring Team,". It must never start with broken text like "'s Name],".
- Keep both outputs ready to copy and paste.

Return ONLY valid JSON with this schema:
{{
  "cover_letter": "full professional cover letter in proper letter format, ready to paste",
  "short_email": "short email version in proper email format, ready to paste",
  "tips": ["tip 1", "tip 2", "tip 3"]
}}

Language: {language or 'English'}
Company name: {company_name or '[Company Name]'}
Target role: {target_role or '[Target Role]'}

Candidate CV:
{cv_text or 'No CV text available.'}

Job description:
{job_description or 'No job description provided.'}
"""
    try:
        result = run_ai_prompt(prompt, json_mode=True)
    except TypeError:
        result = run_ai_prompt(prompt)
    data = _wz52_safe_json(result)
    if not data:
        data = {
            "cover_letter": str(result or "").strip(),
            "short_email": "",
            "tips": [],
        }
    return data



def _wz59_clean_generated_text(text: str, kind: str = "letter") -> str:
    """Light cleanup for generated application text without changing content/features."""
    text = str(text or "").strip()
    # Fix occasional broken greeting caused by model output such as "'s Name],".
    if text.startswith("'s Name],") or text.startswith("[Hiring Manager") is False and text[:12].strip() in {"'s Name],", "s Name],"}:
        text = re.sub(r"^'?s Name\],\s*", "Dear [Hiring Manager's Name],\n\n", text)
    if kind == "email" and text and not re.match(r"(?is)^\s*(dear|hello|hi)\b", text):
        text = "Dear [Hiring Manager's Name],\n\n" + text
    return text

