def _wz59_safe_mobile_go(page_key: str, extra: dict = None):
    try:
        page_key = str(page_key or "dashboard").strip()
        aliases = {
            "home": "dashboard", "landing": "dashboard", "dashboard": "dashboard",
            "cv": "cv_documents", "my_cv": "cv_documents", "cv_documents": "cv_documents",
            "jobs": "job_assist", "job_assist": "job_assist",
            "bot": "workobot", "workobot": "workobot",
            "founder": "founder_dashboard", "founder_dashboard": "founder_dashboard",
        }
        page_key = aliases.get(page_key, "dashboard")
        if extra and isinstance(extra, dict):
            for k, v in extra.items():
                st.session_state[k] = v
        st.session_state["page"] = page_key
        st.session_state["nav_page"] = page_key
        st.session_state["_workzo_scroll_to_top"] = True
        try:
            st.query_params["page"] = page_key
        except Exception:
            pass
        st.rerun()
    except Exception:
        try:
            st.session_state["page"] = page_key
            st.session_state["nav_page"] = page_key
            st.rerun()
        except Exception:
            pass


