def _wz60_render_founder_unlock():
    """Small founder unlock panel. Does not track or expose private data."""
    try:
        founder_pin = None
        try:
            founder_pin = os.getenv("FOUNDER_PIN") or get_streamlit_secret("FOUNDER_PIN")
        except Exception:
            founder_pin = os.getenv("FOUNDER_PIN")

        st.markdown("<div class='workzo-sidebar-section-label'>Founder</div>", unsafe_allow_html=True)
        with st.expander("📊 Founder access", expanded=False):
            if st.session_state.get("founder_unlocked"):
                st.success("Founder mode unlocked.")
                if st.button("Open Founder Dashboard", key="wz60_open_founder_dashboard", use_container_width=True):
                    _wz60_go("founder_dashboard")
            elif founder_pin:
                entered_pin = st.text_input("Founder PIN", type="password", key="wz60_founder_pin")
                if entered_pin and entered_pin == founder_pin:
                    st.session_state["founder_unlocked"] = True
                    st.success("Founder mode unlocked.")
                    _wz60_go("founder_dashboard")
            else:
                temp_pin = st.text_input("Temporary founder PIN", type="password", key="wz60_temp_founder_pin")
                if temp_pin and len(temp_pin) >= 4:
                    st.session_state["founder_unlocked"] = True
                    st.success("Founder mode unlocked for this session.")
                    _wz60_go("founder_dashboard")
    except Exception:
        pass


def _wz35_sidebar(page_key):
    """Final sidebar/toolbox: no company context box, with Real Interview and Founder Dashboard."""
    with st.sidebar:
        try:
            logo_src = image_to_data_uri(ICON_PATH) or image_to_data_uri(LOGO_PATH)
        except Exception:
            logo_src = None

        if logo_src:
            st.markdown(f"""
            <div class='workzo-sidebar-brand-wrap'>
              <img src='{logo_src}' class='workzo-sidebar-logo' alt='WorkZo AI logo'>
              <div>
                <div class='workzo-sidebar-brand'>WORKZO AI</div>
                <div class='workzo-sidebar-version'>Beta · guided workspace</div>
              </div>
            </div>
            """, unsafe_allow_html=True)
        else:
            st.markdown("### WorkZo AI")

        st.markdown("<div class='workzo-sidebar-section-label'>Toolbox</div>", unsafe_allow_html=True)

        navs = [
            ("dashboard", "Dashboard"),
            ("cv_documents", "CV & Documents"),
            ("job_assist", "Job Assist"),
            ("real_interview", "Real Interview Stimulator"),
            ("workobot", "Work-O-Bot"),
        ]

        for key, label in navs:
            shown = label + (" ✓" if page_key == key else "")
            if st.button(shown, key=f"wz60_sidebar_nav_{key}", use_container_width=True):
                _wz60_go(key)

        # Company Context intentionally removed from the toolbox.
        # Company / role / website are now entered inside Real Interview Stimulator.

        st.markdown("<div class='workzo-sidebar-section-label'>Language</div>", unsafe_allow_html=True)
        try:
            langs = language_options if "language_options" in globals() and language_options else ["English", "German", "Dutch", "French", "Spanish", "Portuguese"]
        except Exception:
            langs = ["English", "German", "Dutch", "French", "Spanish", "Portuguese"]

        cur = st.session_state.get("preferred_language") or st.session_state.get("language") or "English"
        if cur not in langs:
            cur = "English" if "English" in langs else langs[0]

        def _wz60_language_changed():
            _new_lang = st.session_state.get("wz60_preferred_language", cur)
            try:
                if callable(globals().get("workzo_set_language_everywhere")):
                    workzo_set_language_everywhere(_new_lang)
                else:
                    set_single_preferred_language(_new_lang)
                try:
                    st.query_params["wz_lang"] = _new_lang
                except Exception:
                    pass
            except Exception:
                pass

        if st.session_state.get("wz60_preferred_language") != cur:
            st.session_state["wz60_preferred_language"] = cur

        chosen = st.selectbox(
            "Select a Language",
            langs,
            index=langs.index(cur),
            key="wz60_preferred_language",
            on_change=_wz60_language_changed,
        )
        try:
            if callable(globals().get("_wz35_sync_language")):
                _wz35_sync_language(chosen)
            else:
                set_single_preferred_language(chosen)
        except Exception:
            pass

        _wz60_render_founder_unlock()

        st.markdown("---")
        if st.button("Edit Onboarding", key="wz60_edit_setup", use_container_width=True):
            try:
                reset_onboarding()
            except Exception:
                st.session_state["onboarding_complete"] = False
                st.session_state["page"] = "onboarding"
                st.session_state["nav_page"] = "onboarding"
            try:
                st.query_params["page"] = "onboarding"
            except Exception:
                pass
            st.rerun()


