                st.markdown(f"""<div class='wz72-step {cls}'><div class='wz72-step-title'>{'✓' if done else '○'} {label}</div><div class='wz72-step-small'>{_wz72_t('Completed') if done else hint}</div></div>""", unsafe_allow_html=True)
