# =========================================================
# WorkZo v181 - Custom HTML/CSS Interview Simulator Dashboard
# Purpose:
# - Stable custom HTML/CSS dashboard, while keeping existing AI/feature logic untouched.
# - WorkZo logo added, Improve CV added to Toolbox, and compact robot Work-O-Bot floating button.
# =========================================================

_WZ181_LOGO_DATA_URI = "data:image/png;base64,"


def _wz181_safe(v, default=""):
    try:
        s = str(v if v is not None else default).strip()
        return s if s else default
    except Exception:
        return default


def _wz181_route(action: str):
    try:
        action = str(action or "").strip().lower()
        aliases = {
            "dashboard": "real_interview", "home": "real_interview", "real_interview": "real_interview",
            "interview_lab": "real_interview", "question_bank": "real_interview",
            "improve_cv": "cv_documents", "resume_review": "cv_documents", "resume_analyzer": "cv_documents",
            "cover_letter": "cv_documents",
            "understand_job": "job_assist", "find_jobs": "job_assist", "prepare_job": "job_assist",
            "workobot": "workobot", "career_advice": "workobot", "interview_coach": "workobot",
        }
        target = aliases.get(action, action or "real_interview")
        for k in ["wz104_more_open", "wz146_more_open", "wz75_workobot_open", "wz181_toolbox_open"]:
            st.session_state.pop(k, None)
        if action in {"improve_cv", "resume_review", "resume_analyzer"}:
            st.session_state["document_tools_mode"] = "Improve / Update CV"
            st.session_state["cv_documents_mode"] = "improve_cv"
            st.session_state["wz168_forced_doc_mode"] = "improve_cv"
        elif action == "cover_letter":
            st.session_state["document_tools_mode"] = "Cover Letter Generator + Language"
            st.session_state["cv_documents_mode"] = "cover_letter"
            st.session_state["wz168_forced_doc_mode"] = "cover_letter"
            st.session_state["wz108_direct_document_tool"] = "cover_letter"
        elif action == "find_jobs":
            st.session_state["wz168_forced_job_mode"] = "find"
            st.session_state["job_assist_mode_key"] = "find"
            st.session_state["wz108_direct_job_mode"] = "find"
        elif action == "understand_job":
            st.session_state["wz168_forced_job_mode"] = "understand"
            st.session_state["job_assist_mode_key"] = "understand"
            st.session_state["wz108_direct_job_mode"] = "understand"
        elif action == "prepare_job":
            st.session_state["wz168_forced_job_mode"] = "prepare"
            st.session_state["job_assist_mode_key"] = "prepare"
            st.session_state["wz108_direct_job_mode"] = "prepare"
        st.session_state["onboarding_complete"] = True
        st.session_state["page"] = target
        st.session_state["nav_page"] = target
        st.session_state["current_page"] = target
        st.session_state["_wz_force_page"] = target
        try:
            st.query_params["page"] = target
            if target == "job_assist":
                st.query_params["mode"] = st.session_state.get("wz168_forced_job_mode", "find")
            elif target == "cv_documents":
                st.query_params["mode"] = st.session_state.get("wz168_forced_doc_mode", "improve_cv")
            else:
                st.query_params.pop("mode", None)
        except Exception:
            pass
        st.rerun()
    except Exception:
        pass


