def _wz181_interactive_controls():
    with st.expander("⚙ Advanced Interview Setup", expanded=False):
        c1, c2 = st.columns(2)
        with c1:
            recruiter = st.selectbox("Who are you interviewing with?", ["👩 Sarah — Friendly HR", "👨 Daniel — Technical Hiring Manager", "👩 Priya — Fast-paced Startup Recruiter", "👨 Markus — German Corporate Interviewer"], key="wz_ri_recruiter_personality_v181")
            st.caption({"👩 Sarah — Friendly HR": "Supportive and communication-focused.", "👨 Daniel — Technical Hiring Manager": "Analytical and detail-oriented.", "👩 Priya — Fast-paced Startup Recruiter": "Fast-paced and impact-focused.", "👨 Markus — German Corporate Interviewer": "Structured and process-oriented."}.get(recruiter, ""))
            st.selectbox("Recruiter style", ["Balanced", "Behavioral-heavy", "Technical-heavy", "Fast-paced", "Leadership-focused"], key="wz_ri_recruiter_style_v181")
        with c2:
            st.selectbox("Country adaptation", ["Auto-detect from role/company", "Germany", "USA", "UK", "India"], key="wz_ri_country_adaptation_v181")
            st.selectbox("How tough should this recruiter be?", ["🙂 Supportive", "😐 Realistic", "🥵 Challenging", "🔥 Brutal recruiter"], key="wz_ri_difficulty_v181")
            st.checkbox("Interrupt vague answers", value=True, key="wz_ri_interrupt_v181")
            st.checkbox("Ask for measurable impact", value=True, key="wz_ri_metrics_v181")
            st.checkbox("Track weak areas", value=True, key="wz_ri_memory_v181")
    if st.button("🎙 Start Real Interview", key="wz181_start_real_interview", type="primary", use_container_width=True):
        st.session_state["wz_ri_started"] = True
        st.session_state["page"] = "real_interview"
        st.session_state["nav_page"] = "real_interview"
        try:
            if callable(globals().get("start_real_interview")):
                start_real_interview()
        except Exception:
            pass
        st.rerun()


def _wz181_floating_workobot():
    try:
        current_page = str(st.session_state.get("nav_page") or st.session_state.get("page") or "").lower()
        if current_page == "workobot":
            return
        with st.container(key="wz181_float_bot"):
            if st.button("🤖", key="wz181_float_bot_button", help="Need career help? Click me"):
                _wz181_route("workobot")
    except Exception:
        pass

try:
    _wz181_previous_show_dashboard = show_dashboard
except Exception:
    _wz181_previous_show_dashboard = None


def show_dashboard():
    try:
        page_key = str(st.session_state.get("_wz_force_page") or st.session_state.get("nav_page") or st.session_state.get("page") or "real_interview").strip().lower()
        try:
            qp = st.query_params.get("page", "")
            if isinstance(qp, (list, tuple)):
                qp = qp[0] if qp else ""
            qp = str(qp or "").strip().lower()
            if qp:
                page_key = qp
        except Exception:
            pass
        if page_key in {"workobot", "work-o-bot", "work_o_bot", "bot"} and callable(globals().get("_wz150_render_workobot_page")):
            return _wz150_render_workobot_page()
        if page_key not in {"", "dashboard", "home", "main", "real_interview", "interview", "interview_practice"}:
            if callable(_wz181_previous_show_dashboard):
                return _wz181_previous_show_dashboard()
        st.session_state["onboarding_complete"] = True
        st.session_state["page"] = "real_interview"
        st.session_state["nav_page"] = "real_interview"
        st.session_state["_wz_force_page"] = "real_interview"
        _wz181_css()
        _wz181_topbar()
        _wz181_dashboard_html()
        _wz181_interactive_controls()
        _wz181_floating_workobot()
    except Exception as exc:
        st.error(f"Dashboard could not load safely: {exc}")
        if callable(_wz181_previous_show_dashboard):
            return _wz181_previous_show_dashboard()

# -----------------------------------------------------------------------------
# WorkZo v182 - stable topbar/settings/toolbox + universal Work-O-Bot launcher
# Purpose:
# - Keep one consistent logo/name card on dashboard and feature pages.
# - Replace Work-O-Bot top dropdown with Settings (Founder dashboard + Exit).
# - Keep Work-O-Bot as a small floating robot icon button on every feature page.
# - Hide Interview Lab until the feature exists.
# - Route toolbox buttons to the correct pages/modes.
# - Hide old Job Assist mode radio buttons so Find/Understand/Prepare feel separate.
# -----------------------------------------------------------------------------

def _wz182_safe_text(value, default=""):
    try:
        value = str(value or "").strip()
        return value if value else default
    except Exception:
        return default


def _wz182_route(action: str):
    """Single source of truth for topbar/toolbox/floating bot navigation."""
    action = str(action or "").strip().lower().replace(" ", "_").replace("-", "_")
    aliases = {
        "dashboard": "real_interview",
        "home": "real_interview",
        "real_interview": "real_interview",
        "improve_cv": "cv_documents",
        "resume_review": "cv_documents",
        "resume_analyzer": "cv_documents",
        "cover_letter": "cv_documents",
        "understand_job": "job_assist",
        "find_jobs": "job_assist",
        "prepare_job": "job_assist",
        "workobot": "workobot",
        "work_o_bot": "workobot",
        "bot": "workobot",
        "career_advice": "workobot",
        "interview_coach": "workobot",
        "founder_dashboard": "founder_dashboard",
    }
    target = aliases.get(action, action or "real_interview")

    # Close any open menus from old versions.
    for k in [
        "wz104_more_open", "wz146_more_open", "wz75_workobot_open", "wz181_toolbox_open",
        "wz182_settings_open", "wz182_toolbox_open"
    ]:
        st.session_state.pop(k, None)

    # Document tools modes.
    if action in {"improve_cv", "resume_review", "resume_analyzer"}:
        st.session_state["document_tools_mode"] = "Improve / Update CV"
        st.session_state["cv_documents_mode"] = "improve_cv"
        st.session_state["wz168_forced_doc_mode"] = "improve_cv"
        st.session_state["wz108_direct_document_tool"] = "improve_cv"
    elif action == "cover_letter":
        st.session_state["document_tools_mode"] = "Cover Letter Generator + Language"
        st.session_state["cv_documents_mode"] = "cover_letter"
        st.session_state["wz168_forced_doc_mode"] = "cover_letter"
        st.session_state["wz108_direct_document_tool"] = "cover_letter"
        st.session_state["wz104_last_tool_action"] = "Cover Letter Generator"

    # Job Assist modes. These keep Find Jobs / Understand Job / Prepare Job separated.
    elif action == "find_jobs":
        st.session_state["wz168_forced_job_mode"] = "find"
        st.session_state["job_assist_mode_key"] = "find"
        st.session_state["wz108_direct_job_mode"] = "find"
        st.session_state["wz182_job_direct_mode"] = "find"
    elif action == "understand_job":
        st.session_state["wz168_forced_job_mode"] = "understand"
        st.session_state["job_assist_mode_key"] = "understand"
        st.session_state["wz108_direct_job_mode"] = "understand"
        st.session_state["wz182_job_direct_mode"] = "understand"
    elif action == "prepare_job":
        st.session_state["wz168_forced_job_mode"] = "prepare"
        st.session_state["job_assist_mode_key"] = "prepare"
        st.session_state["wz108_direct_job_mode"] = "prepare"
        st.session_state["wz182_job_direct_mode"] = "prepare"

    if action == "founder_dashboard":
        st.session_state["founder_mode"] = True
        target = "founder_dashboard"

    st.session_state["onboarding_complete"] = True
    st.session_state["page"] = target
    st.session_state["nav_page"] = target
    st.session_state["current_page"] = target
    st.session_state["_wz_force_page"] = target
    try:
        st.query_params["page"] = target
        if target == "job_assist":
            st.query_params["mode"] = st.session_state.get("wz182_job_direct_mode", st.session_state.get("wz168_forced_job_mode", "find"))
        elif target == "cv_documents":
            st.query_params["mode"] = st.session_state.get("wz168_forced_doc_mode", "improve_cv")
        else:
            st.query_params.pop("mode", None)
    except Exception:
        pass
    st.rerun()


def _wz182_exit_to_landing():
    """Exit current product flow safely back to landing/onboarding."""
    for key in ["onboarding_complete", "page", "nav_page", "current_page", "_wz_force_page", "founder_mode"]:
        st.session_state.pop(key, None)
    try:
        st.query_params.clear()
    except Exception:
        pass
    st.rerun()


