def _wz182_get_page_key():
    page_key = str(st.session_state.get("_wz_force_page") or st.session_state.get("nav_page") or st.session_state.get("page") or "real_interview").strip().lower()
    try:
        qp = st.query_params.get("page", "")
        if isinstance(qp, (list, tuple)):
            qp = qp[0] if qp else ""
        qp = str(qp or "").strip().lower()
        if qp:
            page_key = qp
    except Exception:
        pass
    return page_key or "real_interview"


def _wz182_apply_direct_mode_from_query():
    try:
        mode = st.query_params.get("mode", "")
        if isinstance(mode, (list, tuple)):
            mode = mode[0] if mode else ""
        mode = str(mode or "").strip().lower()
        if mode in {"find", "understand", "prepare"}:
            st.session_state["wz168_forced_job_mode"] = mode
            st.session_state["job_assist_mode_key"] = mode
            st.session_state["wz108_direct_job_mode"] = mode
            st.session_state["wz182_job_direct_mode"] = mode
        elif mode in {"improve_cv", "cover_letter"}:
            if mode == "cover_letter":
                st.session_state["document_tools_mode"] = "Cover Letter Generator + Language"
                st.session_state["cv_documents_mode"] = "cover_letter"
                st.session_state["wz108_direct_document_tool"] = "cover_letter"
            else:
                st.session_state["document_tools_mode"] = "Improve / Update CV"
                st.session_state["cv_documents_mode"] = "improve_cv"
                st.session_state["wz108_direct_document_tool"] = "improve_cv"
    except Exception:
        pass


def show_dashboard():
    """v182 final dashboard router: consistent topbar, correct toolbox routing, universal bot icon."""
    try:
        _wz182_apply_direct_mode_from_query()
        page_key = _wz182_get_page_key()
        st.session_state["onboarding_complete"] = True

        # Work-O-Bot page: render only the bot page, not the floating button.
        if page_key in {"workobot", "work-o-bot", "work_o_bot", "bot"}:
            _wz182_css()
            _wz182_topbar()
            if callable(globals().get("_wz150_render_workobot_page")):
                return _wz150_render_workobot_page()
            if callable(globals().get("show_workobot")):
                return show_workobot()
            st.warning("Work-O-Bot is not available in this build.")
            return

        # Feature pages: same approved topbar + small floating robot icon.
        if page_key not in {"", "dashboard", "home", "main", "real_interview", "interview", "interview_practice"}:
            _wz182_css()
            _wz182_topbar()
            if page_key == "job_assist":
                st.markdown('<div class="wz182-hide-job-tabs"></div>', unsafe_allow_html=True)
            if callable(_wz182_legacy_dashboard_renderer):
                result = _wz182_legacy_dashboard_renderer()
            else:
                result = None
            _wz182_floating_workobot()
            return result

        # Main dashboard: keep the HTML dashboard and do not render old dashboard variants.
        st.session_state["page"] = "real_interview"
        st.session_state["nav_page"] = "real_interview"
        st.session_state["current_page"] = "real_interview"
        st.session_state["_wz_force_page"] = "real_interview"
        _wz182_css()
        _wz182_topbar()
        _wz181_dashboard_html()
        _wz181_interactive_controls()
        _wz182_floating_workobot()
    except Exception as exc:
        st.error(f"WorkZo dashboard could not load safely: {exc}")
        if callable(_wz182_legacy_dashboard_renderer):
            return _wz182_legacy_dashboard_renderer()


# =========================================================
# WorkZo v183 - Density + Progressive Disclosure Dashboard
