def _wz183_personality_caption(value: str) -> str:
    value = str(value or "")
    if "Daniel" in value:
        return "Analytical, technical, detail-oriented. Pushes on SQL, logic, and validation."
    if "Priya" in value:
        return "Fast-paced, impact-focused. Pushes for concise business outcomes."
    if "Markus" in value:
        return "Structured, formal, process-oriented. Pushes for clarity and evidence."
    return "Supportive and communication-focused. Helps you recover while still asking follow-ups."


def _wz183_country_caption(country: str) -> str:
    c = str(country or "").lower()
    if "usa" in c or "united states" in c or c == "us":
        return "achievement-focused interviews"
    if "uk" in c or "united kingdom" in c:
        return "balanced, professional communication"
    if "india" in c:
        return "skills, projects, and ATS-heavy hiring"
    if "germany" in c or "deutsch" in c:
        return "structured & detail-focused interviews"
    return "local recruiter expectations applied"


